/// Compte une source. `files` : `(chemin, taille en octets)`.
pub fn survey<'a>(files: impl IntoIterator<Item = (&'a str, u64)>, policy: impl Fn(&str, u64) -> Kept) -> Survey {
    let mut s = Survey::default();
    for (path, bytes) in files {
        let (bucket, label) = match policy(path, bytes) {
            Kept::Yes(kind) => {
                s.files += 1;
                s.bytes += bytes;
                (&mut s.kept, kind)
            }
            Kept::No(reason) => (&mut s.skipped, reason),
        };
        let entry = bucket.entry(label.to_string()).or_insert((0, 0));
        entry.0 += 1;
        entry.1 += bytes;
    }
    s
}

/// Fait tourner le régulateur sur `texts` textes de `len` caractères et
/// rend, lot par lot, `(caractères, durée)`.
fn run(pacer: &mut BurstPacer, embedder: &FakeEmbedder, texts: usize, len: usize) -> Vec<(usize, Duration)> {
    let lens = vec![len; texts];
    let mut pos = 0;
    let mut bursts = Vec::new();
    while pos < lens.len() {
        let range = next_batch(&lens, pos, usize::MAX, pacer.budget(), usize::MAX);
        let chars: usize = lens[range.clone()].iter().sum();
        let took = embedder.took(chars);
        pacer.record(chars, took);
        bursts.push((chars, took));
        pos = range.end;
    }
    bursts
}

